-- Production schema metadata read on 2026-10-02; no business rows.
-- All native column names/types are retained; inserts below use explicit test columns.
create table public.wg_recharge_details (
 "system" text,
 "country" text,
 "platform" text,
 "site_code" text,
 "business" text,
 "order_number" text,
 "third_order_number" text,
 "member_id" text,
 "provider" text,
 "channel" text,
 "utr" text,
 "status_code" integer,
 "status_group" text,
 "created_at" timestamp with time zone,
 "success_at" timestamp with time zone,
 "updated_at" timestamp with time zone,
 "operated_at" timestamp with time zone,
 "completion_at_unverified" timestamp with time zone,
 "captured_at" timestamp with time zone,
 "member_currency" text,
 "member_unit_scale" integer,
 "member_amount_units" numeric,
 "member_amount" numeric,
 "settlement_currency" text,
 "settlement_amount" numeric,
 "settlement_fee" numeric,
 "exchange_rate" numeric,
 "source_fields" jsonb,
 "version_at" timestamp with time zone,
 "content_hash" text,
 "stored_at" timestamp with time zone,
 "business_fields" jsonb);
alter table public.wg_recharge_details enable row level security;
create index wg_recharge_site_provider on public.wg_recharge_details(site_code,provider);

